const body = $input.first().json.body ?? $input.first().json;

const now = $now.setZone('Asia/Manila');
const items = Array.isArray(body.items) ? body.items : [];
const itemsSummary = items.map(i => `${i.name} x${i.qty}`).join(', ');

return [{
  json: {
    OrderNumber: body.orderNumber,
    Day: now.toFormat('cccc'),
    Date: now.toFormat('yyyy-MM-dd'),
    Time: now.toFormat('hh:mm a'),
    Customer: body.customerName || 'Guest',
    Items: itemsSummary,
    Subtotal: body.subtotal,
    Discount: body.discountAmount,
    Tax: body.tax,
    Total: body.total,
    Cost: body.cost || 0,
    Profit: body.profit || 0,
    PaymentMethod: body.paymentMethod,
    OrderType: body.orderType,
    Note: body.note || '',
    Staff: body.staffName || 'Unknown'
  }
}];

const o = $('Format Order').item.json;
return [{
  json: {
    Name: o.Customer,
    LastVisitDay: o.Day,
    LastVisitDate: o.Date,
    LastVisitTime: o.Time,
    LastOrderTotal: o.Total,
    LastPaymentMethod: o.PaymentMethod,
    LastOrderType: o.OrderType
  }
}];

